head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > modifyUncheckStatus]<br/>Body Column 정보를 사용하여 특정 Column 에서 체크되지 않은 Row 의 상태값을 일괄로 변경합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 Body Column 의 ID 를 설정하여 해당 Column 에서 체크되지 않은 Row 의 상태값을 일괄로 변경합니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 컬럼 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] chk(checkbox) / name(text-미동작) / rdo(radio) / cst(custom, Row0/3/4=checkbox·Row1=text·Row2=radio) / memo(text)\n체크된 Row -> chk: 0,2,4 / rdo: 0,2,4 / cst: 0,2,4 (미체크 Row -> 1,3)\n[절차] columnInfo(Column ID) 와 status 선택 후 modifyUncheckStatus 실행\n[확인] 체크되지 않은 Row 만 상태값 변경, 체크된 Row 는 불변. 잘못된 status(X) 는 미실행"', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성
    // - chk  : checkbox(binary) 원본값 1/0
    // - name : text 컬럼 (checkbox/radio 아님 -> 미동작)
    // - rdo  : radio 원본값 1/0
    // - cst  : custom 컬럼 (행별 inputType 부여)
    // - memo : text 컬럼
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="chk" name="chk" dataType="text"></w2:column>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="rdo" name="rdo" dataType="text"></w2:column>';
    strDlt += '<w2:column id="cst" name="cst" dataType="text"></w2:column>';
    strDlt += '<w2:column id="memo" name="memo" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // Row0/Row2/Row4 = 체크(값 "1"), Row1/Row3 = 미체크(값 "0")
    // cst : Row0=checkbox(1=체크), Row1=text, Row2=radio(1=체크), Row3=checkbox(0=미체크), Row4=checkbox(1=체크)
    let jsonData = [
        { "chk": "1", "name": "HONG", "rdo": "1", "cst": "1",    "memo": "메모0" },
        { "chk": "0", "name": "LEE",  "rdo": "0", "cst": "text", "memo": "메모1" },
        { "chk": "1", "name": "KIM",  "rdo": "1", "cst": "1",    "memo": "메모2" },
        { "chk": "0", "name": "PARK", "rdo": "0", "cst": "0",    "memo": "메모3" },
        { "chk": "1", "name": "CHOI", "rdo": "1", "cst": "1",    "memo": "메모4" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정은 createCList 공통 함수 사용
    // - setCellInputTypeCustom=true -> custom 컬럼에 setCellInputType 으로 행별 inputType 부여 가능
    // - rowStatusVisible=true -> 변경된 Row 상태값을 그리드에서 확인
    let properties = {
        dataList: "data:dlt_bind",
        setCellInputTypeCustom: "true",
        rowStatusVisible: "true",
        checkAllType: "false",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // target 생성 (Header 5컬럼)
    // 마지막 memo 컬럼 width="*" 로 가로 스크롤 방지
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:640px;height:280px;">';
    strTarget += '<w2:caption style="" id="caption1" value="modifyUncheckStatus 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="110" style="" inputType="text" id="hcol1" value="chk(checkbox)"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="hcol2" value="name(text)"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="hcol3" value="rdo(radio)"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="hcol4" value="cst(custom)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol5" value="memo(text)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    // index 0 : chk (checkbox, valueType=binary) - trueValue="1" falseValue="0"
    strTarget += '<w2:column width="110" style="" inputType="checkbox" valueType="binary" id="chk" dataList="chk" trueValue="1" falseValue="0"></w2:column>';
    // index 1 : name (text) - checkbox/radio 아님 -> 미동작
    strTarget += '<w2:column width="100" style="" inputType="text" id="name" dataList="name"></w2:column>';
    // index 2 : rdo (radio, valueType=binary) - trueValue="1" falseValue="0"
    strTarget += '<w2:column width="100" style="" inputType="radio" valueType="binary" id="rdo" dataList="rdo" trueValue="1" falseValue="0"></w2:column>';
    // index 3 : cst (custom) - 행별 inputType 혼합 (setCellInputType 으로 지정)
    strTarget += '<w2:column width="110" style="" inputType="custom" id="cst" dataList="cst" trueValue="1" falseValue="0"></w2:column>';
    // index 4 : memo (text) - width="*"
    strTarget += '<w2:column width="*" style="" inputType="text" id="memo" dataList="memo"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // cst(custom) 컬럼 행별 inputType 부여 (@spec1)
    //  Row0 = checkbox(1=체크), Row1 = text(체크 대상 아님), Row2 = radio(1=체크), Row3 = checkbox(0=미체크), Row4 = checkbox(1=체크)
    target1.setCellInputType(0, "cst", { inputType: "checkbox" });
    target1.setCellInputType(1, "cst", { inputType: "text" });
    target1.setCellInputType(2, "cst", { inputType: "radio" });
    target1.setCellInputType(3, "cst", { inputType: "checkbox" });
    target1.setCellInputType(4, "cst", { inputType: "checkbox" });
}



// modifyUncheckStatus 실행 : par_columnInfo(Column ID) / par_status 로 호출
//  - columnInfo 는 Column ID(String) 로 전달 -> 해당 컬럼에서 체크되지 않은 Row 의 상태만 일괄 변경
//  - status 가 'R','U','C','D','V' 이외 값(X) 이면 메소드 미실행(상태 불변)
scwin.btn_modifyUncheckStatus_onclick = function () {
    // columnInfo 는 Column ID(String) 로 전달
    let colId = par_columnInfo.getValue();
    let status = par_status.getValue();

    // 대상 컬럼에서 체크되지 않은 Row 인덱스 (검증용)
    let uncheckedRows = target1.getUncheckedIndex(colId);

    // 실행 전 전체 Row 의 상태값
    let total = dlt_bind.getRowCount();
    let before = [];
    for (let i = 0; i < total; i++) before.push(dlt_bind.getRowStatus(i));

    // modifyUncheckStatus 실행 : 체크되지 않은 Row 상태 일괄 변경
    target1.modifyUncheckStatus(colId, status);

    // 실행 후 전체 Row 의 상태값
    let after = [];
    for (let i = 0; i < total; i++) after.push(dlt_bind.getRowStatus(i));

    wf_body_bottom.getObj("scwin").setReturnValue(
        "modifyUncheckStatus('" + colId + "', '" + status + "') / 미체크Row[" + uncheckedRows + "] / 상태 [" + before + "] -> [" + after + "]");
}
